 * Purpose: Firestore implementation of RatingRepository.
 * Role / Design Pattern: Repository Pattern implementation.
 * Outstanding Issues: Client-side checks only; Firestore security rules should enforce them too.
 */
package com.example.campsitelottery

import com.google.firebase.firestore.FieldValue
import com.google.firebase.firestore.FirebaseFirestore

/**
 * Stores each rating at `campsites/{campsiteId}/ratings/{userId}`, so a user has at
 * most one rating per campsite. The campsite's `ratingSum`, `ratingCount` and
 * `rating` (average) are updated in the same transaction as the rating itself, so
 * two users rating at the same time can't overwrite each other's totals.
 */
class FirestoreRatingRepository(
    private val db: FirebaseFirestore = FirebaseFirestore.getInstance(),
) : RatingRepository {

    private fun campsite(campsiteId: String) = db.collection("campsites").document(campsiteId)

    private fun ratingDoc(campsiteId: String, userId: String) =
        campsite(campsiteId).collection("ratings").document(userId)

    override fun getMyRating(
        campsiteId: String,
        userId: String,
        onSuccess: (Int?) -> Unit,
        onFailure: (Exception) -> Unit,
    ) {
        if (campsiteId.isBlank() || userId.isBlank()) return onSuccess(null)
        ratingDoc(campsiteId, userId).get()
            .addOnSuccessListener { doc -> onSuccess(doc.getLong("stars")?.toInt()) }
            .addOnFailureListener(onFailure)
    }

    override fun submitRating(
        campsiteId: String,
        userId: String,
        stars: Int,
        onSuccess: (RatingPolicy.Totals) -> Unit,
        onFailure: (Exception) -> Unit,
    ) {
        try {
            require(campsiteId.isNotBlank() && userId.isNotBlank()) { "Missing campsite or user." }
            RatingPolicy.requireValid(stars)
        } catch (e: IllegalArgumentException) {
            return onFailure(e)
        }
        val siteRef = campsite(campsiteId)
        val ratingRef = ratingDoc(campsiteId, userId)

        db.runTransaction { tx ->
            val site = tx.get(siteRef)
            check(site.exists()) { "This campsite no longer exists." }
            check(RatingPolicy.canRate(site.getString("ownerId").orEmpty(), userId)) {
                "You can't rate your own campsite."
            }
            val previous = tx.get(ratingRef).getLong("stars")?.toInt()
            val current = RatingPolicy.Totals(
                sum = site.getLong("ratingSum") ?: 0L,
                count = (site.getLong("ratingCount") ?: 0L).toInt(),
            )
            val updated = RatingPolicy.apply(current, previous, stars)

            tx.set(
                ratingRef,
                mapOf(
                    "userId" to userId,
                    "stars" to stars,
                    "updatedAt" to FieldValue.serverTimestamp(),
                ),
            )
            tx.update(
                siteRef,
                mapOf(
                    "ratingSum" to updated.sum,
                    "ratingCount" to updated.count,
                    "rating" to updated.average,
                ),
            )
            updated
        }
            .addOnSuccessListener { onSuccess(it) }
            .addOnFailureListener(onFailure)
    }
}
